const root = document.querySelector('#content');
let me = null, view = '', catalog = { vehicles: [], addresses: [], services: [], googleMapsApiKey: null }, bookings = [], workerProfile = null;
let customerCacheLoaded = false, customerLoadPromise = null, renderSequence = 0;
let deferredInstallPrompt = null, installDialogOpen = false;
const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
const money = paise => new Intl.NumberFormat('en-IN', { style:'currency', currency:'INR', maximumFractionDigits:0 }).format(Number(paise||0)/100);
const date = x => new Date(x).toLocaleString('en-IN', { dateStyle:'medium', timeStyle:'short' });
function visibleCustomerServices(items){const seen=new Set(),rank=s=>s.category==='SOLAR'&&/solar\s+panel\s+wash/i.test(s.name)?0:1;return [...items].sort((a,b)=>rank(a)-rank(b)).filter(s=>{const name=String(s.name||'').trim().toLocaleLowerCase().replace(/\s+/g,' '),key=s.category==='SOLAR'?'SOLAR|'+s.zoneId:[s.category||'VEHICLE',s.vehicleType||'',s.zoneId||'',name].join('|');if(seen.has(key))return false;seen.add(key);return true})}
const statusText = { CREATED:'Ready to pay', QUOTE_REQUESTED:'Quote in review', QUOTE_PROVIDED:'Quote ready', PAYMENT_PENDING:'Payment pending', PAID:'Paid', ASSIGNING:'Finding a worker', ASSIGNED:'Assigned', WORKER_ON_THE_WAY:'Worker on the way', IN_PROGRESS:'In progress', PHOTOS_UPLOADED:'Photos in review', APPROVED:'Approved', COMPLETED:'Completed', CANCELLED:'Cancelled', REJECTED_PHOTOS:'Photos need retaking', REFUNDED:'Refunded', NO_WORKER_FOUND:'No worker found' };
function statusBadge(status){const label=statusText[status]||String(status||'').replaceAll('_',' ');const tone=['COMPLETED','APPROVED','PAID'].includes(status)?'done':['PAYMENT_PENDING','ASSIGNING','PHOTOS_UPLOADED'].includes(status)?'pending':['CANCELLED','REJECTED_PHOTOS','REFUNDED','NO_WORKER_FOUND'].includes(status)?'cancelled':['ASSIGNED','WORKER_ON_THE_WAY','IN_PROGRESS'].includes(status)?'info':'';return '<span class="badge '+tone+'">'+esc(label)+'</span>'}
async function api(url, opts={}) { const started=performance.now();try{const r=await fetch(url,{credentials:'same-origin',...opts,headers:{'Content-Type':'application/json',...(opts.headers||{})}});if(r.status===204){if(opts.method&&opts.method!=='GET'&&url.startsWith('/api/v1/'))customerCacheLoaded=false;return null}const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Request failed');if(opts.method&&opts.method!=='GET'&&url.startsWith('/api/v1/'))customerCacheLoaded=false;return d}finally{console.info('QuickWashHub API',JSON.stringify({path:url.split('?')[0].replace(/\/[a-z0-9_-]{20,}/gi,'/:id'),durationMs:Math.round(performance.now()-started)}))} }
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),3500)}
function isInstalled(){if(window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true)return true;try{return localStorage.getItem('quickwashhub:installed')==='1'}catch{return false}}
function promptKey(){return 'quickwashhub:pwa-install-prompted:'+(me?.id||me?.email||'customer')}
function setInstallButton(){const b=document.querySelector('#install-app');if(!b)return;b.classList.toggle('hidden',!deferredInstallPrompt||isInstalled())}
function closeInstallDialog(markSeen=true){const modal=document.querySelector('#install-dialog');if(modal)modal.remove();installDialogOpen=false;if(markSeen&&me?.role==='CUSTOMER'){try{localStorage.setItem(promptKey(),'1')}catch{}}}
async function installApp(){if(!deferredInstallPrompt){toast('Direct installation is not available in this browser.');return}const promptEvent=deferredInstallPrompt;deferredInstallPrompt=null;setInstallButton();try{await promptEvent.prompt();const choice=await promptEvent.userChoice;if(choice?.outcome==='accepted'){try{localStorage.setItem('quickwashhub:installed','1')}catch{};toast('QuickWashHub is being installed.')}else setInstallButton()}catch{toast('The browser could not open the install prompt.')}closeInstallDialog();}
function showFirstInstallDialog(){if(!me||me.role!=='CUSTOMER'||isInstalled()||installDialogOpen)return;try{if(localStorage.getItem(promptKey()))return}catch{};installDialogOpen=true;const modal=document.createElement('div');modal.className='backdrop';modal.id='install-dialog';modal.setAttribute('role','presentation');modal.innerHTML='<section class="modal install-modal" role="dialog" aria-modal="true" aria-labelledby="install-title"><div class="install-mark" aria-hidden="true">Q</div><div class="eyebrow">QUICK ACCESS</div><h2 id="install-title">Take QuickWashHub with you</h2><p>Install the app for a faster way to book washes and check your service updates.</p>'+(deferredInstallPrompt?'<div class="install-actions"><button class="primary" id="install-now" type="button">Install app</button><button class="text-button" id="install-later" type="button">Maybe later</button></div>':'<p class="install-unavailable">This browser does not offer a direct install prompt. You can continue using QuickWashHub here.</p><button class="secondary" id="install-later" type="button">Continue</button>')+'</section>';document.body.append(modal);modal.querySelector('#install-now')?.addEventListener('click',installApp);modal.querySelector('#install-later').addEventListener('click',()=>closeInstallDialog());modal.addEventListener('click',e=>{if(e.target===modal)closeInstallDialog()});modal.addEventListener('keydown',e=>{if(e.key==='Escape')closeInstallDialog()});try{modal.querySelector('#install-now,#install-later').focus()}catch{};try{localStorage.setItem(promptKey(),'1')}catch{}}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();if(isInstalled())return;deferredInstallPrompt=event;setInstallButton();if(me?.role==='CUSTOMER')setTimeout(showFirstInstallDialog,100)});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;setInstallButton();try{localStorage.setItem('quickwashhub:installed','1')}catch{};closeInstallDialog()});
document.querySelector('#install-app')?.addEventListener('click',installApp);
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/service-worker.js?v=15',{updateViaCache:'none'}).catch(()=>{}));
function panel(title,body,action){return '<div class="sectionhead"><h3>'+esc(title)+'</h3></div><div class="panel">'+(body||'<p class="fine">Nothing here yet.</p>')+(action||'')+'</div>'}
function heading(title,desc,button){return '<div class="heading"><div><div class="eyebrow">'+esc(me.role)+'</div><h1>'+esc(title)+'</h1><p>'+esc(desc||'')+'</p></div>'+(button||'')+'</div>'}
function authPage(mode='login', email=''){document.querySelector('#crumb').textContent='Sign in';document.querySelector('#logout').classList.add('hidden');document.querySelector('#user').innerHTML='';document.querySelector('#nav').innerHTML='';document.querySelector('#mobile-nav').classList.add('hidden');const verify=mode==='verify',reset=mode==='reset',register=mode==='register';root.innerHTML='<div class="auth-wrap"><section class="auth-card"><div class="eyebrow">CAR & BIKE CARE, AT YOUR DOOR</div><h1>'+({login:'Sign in to QuickWashHub',register:'Create your account',verify:'Verify your email',reset:'Reset your password',forgot:'Reset your password'}[mode])+'</h1><p>'+({login:'Book and manage your car or bike wash.',register:'Use your email to create a secure account.',verify:'Enter the six-digit code sent to your email.',reset:'Enter the code from your email and choose a new password.',forgot:'We’ll email a password reset code if the account exists.'}[mode])+'</p>'+(mode==='login'?'<div class="google-button" id="google-signin" aria-label="Sign in with Google"></div><div class="auth-divider"><span>or continue with email</span></div>':'')+'<form id="auth-form">'+(register?'<label class="field"><span>Your name</span><input name="name" autocomplete="name" required maxlength="100"></label>':'')+'<label class="field"><span>Email address</span><input name="email" type="email" autocomplete="email" required value="'+esc(email)+'" '+(verify||reset?'readonly':'')+'></label>'+(verify||reset?'<label class="field"><span>Six-digit code</span><input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" required></label>':'')+((mode==='login'||register||reset)?'<label class="field"><span>'+(reset?'New password':'Password')+'</span><input name="password" type="password" autocomplete="'+(register||reset?'new-password':'current-password')+'" minlength="10" maxlength="128" required></label>':'')+(register?'<label class="marketing-consent"><input id="marketing-opt-in" name="marketingOptIn" type="checkbox"><span>Email me QuickWashHub offers and service updates on WhatsApp/push where enabled. I can unsubscribe any time.</span></label>':'')+'<button class="primary" type="submit">'+({login:'Sign in',register:'Create account',verify:'Verify email and continue',reset:'Save new password',forgot:'Send reset code'}[mode])+' →</button></form><p class="fine">'+(mode==='login'?'<button class="text-button" id="forgot" type="button">Forgot password?</button>':'')+' '+(mode==='login'?'<button class="text-button" id="register" type="button">Create an account</button>':'<button class="text-button" id="back-login" type="button">Back to sign in</button>')+'</p></section></div>';
 document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));if(register)d.marketingOptIn=document.querySelector('#marketing-opt-in')?.checked===true;try{if(mode==='login'){const result=await api('/api/v1/auth/login',{method:'POST',body:JSON.stringify(d)});if(result.requiresMfa)return adminMfaChallenge(result.challengeToken);await boot()}else if(register){await api('/api/v1/auth/register',{method:'POST',body:JSON.stringify(d)});authPage('verify',d.email);toast('Verification code emailed')}else if(verify){const result=await api('/api/v1/auth/verify-email',{method:'POST',body:JSON.stringify(d)});if(result.requiresMfa)return adminMfaChallenge(result.challengeToken);await boot()}else if(mode==='forgot'){await api('/api/v1/auth/password-reset/request',{method:'POST',body:JSON.stringify(d)});authPage('reset',d.email);toast('If the account exists, a code was emailed')}else if(reset){await api('/api/v1/auth/password-reset/confirm',{method:'POST',body:JSON.stringify(d)});authPage('login',d.email);toast('Password updated')}}catch(err){toast(err.message)}};
 document.querySelector('#register')?.addEventListener('click',()=>authPage('register'));document.querySelector('#forgot')?.addEventListener('click',()=>authPage('forgot'));document.querySelector('#back-login')?.addEventListener('click',()=>authPage('login',email));
 if(mode==='login')api('/api/v1/auth/config').then(cfg=>{if(!cfg.googleClientId){document.querySelector('#google-signin')?.classList.add('hidden');return;}const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.onload=()=>{window.google.accounts.id.initialize({client_id:cfg.googleClientId,callback:async result=>{try{const signedIn=await api('/api/v1/auth/google',{method:'POST',body:JSON.stringify({credential:result.credential})});if(signedIn.requiresMfa)return adminMfaChallenge(signedIn.challengeToken);await boot()}catch(err){toast(err.message)}}});const mount=document.querySelector('#google-signin');const card=mount.closest('.auth-card');const cardStyle=getComputedStyle(card);const availableWidth=Math.floor(card.clientWidth-parseFloat(cardStyle.paddingLeft)-parseFloat(cardStyle.paddingRight));window.google.accounts.id.renderButton(mount,{type:'standard',theme:'outline',size:'large',shape:'rectangular',logo_alignment:'left',width:Math.max(200,Math.min(320,availableWidth)),text:'signin_with'})};document.head.append(script)}).catch(()=>{});
}
function adminMfaChallenge(challengeToken){root.innerHTML='<div class="auth-wrap"><section class="auth-card"><div class="eyebrow">ADMIN SECURITY</div><h1>Verify your sign in</h1><p>Enter the current six-digit code from your authenticator app.</p><form id="mfa-login-form"><label class="field"><span>Authenticator code</span><input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required autofocus></label><button class="primary">Verify and continue →</button></form><p class="fine"><button class="text-button" id="mfa-back" type="button">Back to sign in</button></p></section></div>';document.querySelector('#mfa-login-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/v1/auth/admin/mfa/verify',{method:'POST',body:JSON.stringify({challengeToken,code:e.currentTarget.elements.code.value})});await boot()}catch(error){toast(error.message)}};document.querySelector('#mfa-back').onclick=()=>authPage('login')}
function nav(){const items=me.role==='CUSTOMER'?[['Overview','⌂'],['Bookings','▣'],['Book a wash','＋'],['Vehicles','◇'],['Addresses','⌖'],['Offers & alerts','✦']]:me.role==='WORKER'?[['Job requests','✦'],['My jobs','▣'],['Earnings','₹']]:[['Bookings','▣'],['Workers','♙'],['Photo review','▧'],['Zones & pricing','⌖'],['Services','✧'],['Campaigns','◷'],['Payouts','₹'],['Reports','▤'],['Audit log','≡']];const html=items.map(x=>'<button class="navlink '+(view===x[0]?'active':'')+'" data-nav="'+esc(x[0])+'" type="button"><span class="nav-icon" aria-hidden="true">'+x[1]+'</span><span class="nav-label">'+esc(x[0])+'</span></button>').join('');document.querySelector('#nav').innerHTML=html;document.querySelector('#mobile-nav').innerHTML=html;document.querySelector('#mobile-nav').classList.remove('hidden');document.querySelectorAll('#nav [data-nav],#mobile-nav [data-nav]').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='Book a wash'){openBooking();return}view=b.dataset.nav;render()});}
function setupShell(){document.querySelector('#crumb').textContent=view||'Overview';document.querySelector('#menu-label').textContent=me.role==='CUSTOMER'?'YOUR ACCOUNT':me.role==='WORKER'?'WORKER SPACE':'OPERATIONS';document.querySelector('#logout').classList.remove('hidden');document.querySelector('#user').innerHTML='<i class="avatar">'+esc((me.name||me.email||'U').slice(0,2).toUpperCase())+'</i><div><b>'+esc(me.name||me.email)+'</b><small>'+esc(me.role.toLowerCase())+'</small></div>';document.querySelector('#logout').onclick=async()=>{await api('/api/v1/auth/logout',{method:'POST'});me=null;authPage()};nav();setInstallButton();}
async function refreshCustomer(){if(customerLoadPromise)return customerLoadPromise;customerLoadPromise=Promise.all([api('/api/v1/bootstrap'),api('/api/v1/bookings')]).then(([nextCatalog,nextBookings])=>{catalog=nextCatalog;bookings=nextBookings;customerCacheLoaded=true}).finally(()=>{customerLoadPromise=null});return customerLoadPromise}
function bookingRows(rows,adminView=false){
 if(!rows.length)return '<div class="empty-state"><b>No bookings yet</b>Your washes and booking updates will appear here.</div>';
 const items=rows.map(b=>{let actions='';if(adminView&&['PAID','ASSIGNING'].includes(b.status))actions='<button class="secondary" data-assign="'+esc(b.id)+'" data-zone="'+esc(b.zone?.id||'')+'" data-category="'+esc(b.service?.category||'VEHICLE')+'">Assign worker</button>';if(adminView&&b.payment?.method==='cashfree'&&['VERIFIED','REFUNDED'].includes(b.payment.status)){const remaining=Math.max(0,Number(b.payment.amount||0)-Number(b.payment.refundedAmount||0));if(remaining>0&&b.payment.status==='VERIFIED')actions+='<button class="secondary" data-refund="'+esc(b.id)+'" data-remaining="'+remaining+'">Issue refund</button>';actions+='<button class="secondary" data-reconcile="'+esc(b.id)+'">Reconcile Cashfree</button><small class="subcell">Split '+esc(b.payment.splitStatus||'pending')+' · refunded '+money(b.payment.refundedAmount||0)+' / '+money(b.payment.amount||0)+'</small>';const refundSummary=(b.payment.refunds||[]).map(r=>esc(r.status)+' '+money(r.amount)).join(' · ');if(refundSummary)actions+='<small class="subcell">Refunds: '+refundSummary+'</small>';const vendors=b.payment.reconciliationSnapshot?.split?.vendors||[];if(vendors.length)actions+='<small class="subcell">Vendor settlements: '+vendors.map(v=>esc(v.vendor_id)+' ₹'+Number(v.settlement_amount||0).toFixed(2)).join(' · ')+'</small>'}if(adminView&&b.status==='QUOTE_REQUESTED')actions+='<button class="primary" data-quote="'+esc(b.id)+'">Review and send quote</button>';if(adminView&&['CREATED','PAYMENT_PENDING','QUOTE_PROVIDED'].includes(b.status))actions+='<small class="subcell">Assign after customer payment is confirmed.</small>';if(!adminView&&b.status==='CREATED')actions='<button class="primary" data-pay="'+esc(b.id)+'">Pay</button><button class="secondary" data-cancel="'+esc(b.id)+'">Cancel</button>';if(!adminView&&['PAYMENT_PENDING','QUOTE_PROVIDED'].includes(b.status))actions='<button class="primary" data-pay="'+esc(b.id)+'">'+(b.status==='QUOTE_PROVIDED'?'Review quote and pay':'Continue payment')+'</button>';if(!adminView&&['QUOTE_REQUESTED','QUOTE_PROVIDED'].includes(b.status))actions+='<button class="secondary" data-cancel="'+esc(b.id)+'">Cancel request</button>';if(!adminView&&b.status==='COMPLETED'&&!b.rating)actions+='<button class="secondary" data-rate="'+esc(b.id)+'">Rate</button>';if(!adminView&&b.photos)actions+=b.photos.filter(p=>p.status==='APPROVED').map(p=>'<button class="secondary" data-photo-view="'+esc(p.id)+'">'+esc(p.type==='BEFORE'?'Before photo':'After photo')+'</button>').join('');const service=esc(b.service?.name||b.service||'Wash service'),zone=esc(b.zone?.name||b.zone||''),vehicle=esc(b.vehicle?.model?b.vehicle.model+', '+b.vehicle.number:b.vehicle||b.customer?.name||b.customer?.email||b.customer?.phone||'');const total=b.status==='QUOTE_REQUESTED'?'Quote pending':money(b.price);return {b,actions,service,zone,vehicle,total}});
 const table='<div class="tablewrap desktop-booking-table"><table class="data"><thead><tr><th>Service</th><th>Customer / vehicle</th><th>Scheduled</th><th>Status</th><th>Total</th><th>Actions</th></tr></thead><tbody>'+items.map(({b,actions,service,zone,vehicle,total})=>'<tr><td><b>'+service+'</b><small class="subcell">'+zone+'</small></td><td>'+vehicle+(b.solarPropertyType?'<small class="subcell">'+esc(b.solarPropertyType)+' · '+esc(b.solarPanelCount||'panel count TBD')+' panels · '+esc(b.solarRoofType||'')+'</small>':'')+'</td><td>'+esc(date(b.scheduledAt))+'</td><td>'+statusBadge(b.status)+(b.status==='QUOTE_REQUESTED'?'<small class="subcell">'+esc(b.solarAccessNotes||'Waiting for site review')+'</small>':'')+'</td><td>'+total+'</td><td>'+actions+'</td></tr>').join('')+'</tbody></table></div>';
 const cards=adminView?'':'<div class="booking-cards">'+items.map(({b,actions,service,zone,vehicle,total})=>'<article class="booking-card"><div class="booking-card-top"><div><strong>'+service+'</strong><small>'+zone+'</small></div><b class="price">'+total+'</b></div><div class="booking-card-meta"><span>'+esc(date(b.scheduledAt))+'</span><span>'+vehicle+'</span></div>'+(b.status==='QUOTE_REQUESTED'?'<p class="fine">We’re reviewing your site details and will send a quote before payment.</p>':'')+(b.quoteNote?'<p class="fine">'+esc(b.quoteNote)+'</p>':'')+'<div class="booking-card-bottom">'+statusBadge(b.status)+(actions?'<div class="booking-actions">'+actions+'</div>':'')+'</div></article>').join('')+'</div>';
 return '<div class="booking-list '+(adminView?'admin-booking-list':'customer-booking-list')+'">'+table+cards+'</div>';
}
function customerView(){if(view==='Offers & alerts')return heading('Offers & alerts','Choose whether to receive offers by email and WhatsApp. Push also needs your browser permission.')+panel('Marketing preferences','<form id="marketing-preferences"><label class="marketing-consent"><input type="checkbox" name="optedIn"><span>Send me QuickWashHub offers by email and WhatsApp. I can unsubscribe any time.</span></label><button class="primary" type="submit">Save preferences</button></form><div id="push-settings" class="push-settings"><span class="fine">Checking push support…</span></div>');if(view==='Vehicles')return vehicleView();if(view==='Addresses')return addressView();if(view==='Bookings')return heading('Bookings','View upcoming washes, payment status, and completed services.','<button class="primary" data-book>Book a wash</button>')+bookingRows(bookings);const upcoming=bookings.filter(b=>!['COMPLETED','CANCELLED','REFUNDED'].includes(b.status)).slice(0,1),recent=bookings.filter(b=>['COMPLETED','CANCELLED','REFUNDED'].includes(b.status)).slice(0,3);const services=visibleCustomerServices(catalog.services).filter(s=>s.category==='VEHICLE').map(s=>'<div class="service"><span class="thumb" aria-hidden="true">'+(s.vehicleType==='BIKE'?'◈':'◇')+'</span><div class="info"><strong>'+esc(s.name)+'</strong><small>'+esc(s.vehicleType)+' · '+s.durationMin+' min · '+esc(s.zoneName)+'</small></div><b class="price">'+money(s.price)+'</b></div>').join('');return heading('Hello, '+(me.name||'there'),'Your next wash is lined up.','<button class="primary" data-book>Book a wash</button>')+'<div class="customer-overview"><div class="overview-main">'+panel('Your next wash',bookingRows(upcoming))+(recent.length?panel('Recent bookings',bookingRows(recent)):'')+'</div><aside class="overview-services">'+panel('Available services',services||'<div class="empty-state"><b>No services available yet</b>Check back after services are added in your area.</div>')+'</aside></div>';}
function vehicleView(){return heading('Your vehicles','Only vehicles you add to your account appear here.')+panel('Add a vehicle','<form id="vehicle-form" class="formrow"><label class="field"><span>Type</span><select name="type"><option>CAR</option><option>BIKE</option></select></label><label class="field"><span>Make and model</span><input name="model" required maxlength="80"></label><label class="field"><span>Registration number</span><input name="number" required maxlength="20"></label><button class="primary">Add vehicle</button></form>')+panel('Saved vehicles',catalog.vehicles.map(v=>'<div class="row"><div class="info"><strong>'+esc(v.model)+'</strong><small>'+esc(v.type)+' · '+esc(v.number)+'</small></div><button class="secondary" data-delete-vehicle="'+esc(v.id)+'">Remove</button></div>').join(''));}
function addressView(){return heading('Service addresses','Choose an address suggestion or pin your location. We’ll check it before saving.')+panel('Add a service address','<form id="address-form"><label class="field field-wide"><span>Search for your road, building or locality</span><div id="address-autocomplete" class="place-autocomplete-host"></div></label><div class="location-toolbar"><button class="primary" id="use-current-location" type="button">◎ Use my current location</button><span id="location-status" class="fine" role="status">Choose a suggestion, use GPS, or move the map pin. Address will fill automatically.</span></div><div id="address-map-wrap"><div id="address-map" aria-label="Choose your service location on the map"></div><p class="form-help">Drag the pin or tap the map to adjust the pickup point.</p></div><input type="hidden" name="lat"><input type="hidden" name="lng"><div class="formrow"><label class="field"><span>Save as</span><input name="label" placeholder="Home, work…" autocomplete="address-line1" required maxlength="50"></label><label class="field"><span>Detected address</span><input name="addressLine" placeholder="Choose a suggestion or use your location" autocomplete="street-address" minlength="5" required maxlength="250"></label><label class="field field-wide"><span>Nearby landmark or exact directions</span><input name="details" placeholder="For example: in front of the blue gate, near the temple" maxlength="200" autocomplete="address-line2"></label></div><div id="address-validation-status" class="address-validation-status" role="status" aria-live="polite"></div><button class="primary" type="submit">Verify address and save →</button></form>')+panel('Saved addresses',catalog.addresses.map(a=>'<div class="row"><div class="info"><strong>'+esc(a.label)+'</strong><small>'+esc(a.fullAddress)+' · '+esc(a.zone?.name||'Service area assigned')+'</small></div><button class="secondary" data-delete-address="'+esc(a.id)+'">Remove</button></div>').join(''));}
let addressMap=null,addressMarker=null,addressGeocoder=null,addressMapsLoad=null;
function loadGoogleMaps(){if(window.google?.maps)return Promise.resolve();if(addressMapsLoad)return addressMapsLoad;if(!catalog.googleMapsApiKey)return Promise.reject(Error('Google Maps is not configured.'));addressMapsLoad=new Promise((resolve,reject)=>{window.quickWashHubGoogleMapsReady=()=>resolve();const script=document.createElement('script');script.src='https://maps.googleapis.com/maps/api/js?key='+encodeURIComponent(catalog.googleMapsApiKey)+'&loading=async&callback=quickWashHubGoogleMapsReady';script.async=true;script.onerror=()=>reject(Error('Google Maps could not load.'));document.head.append(script)});return addressMapsLoad}
async function mountAddressAutocomplete(host,selectPlace,map){if(!host)return;try{const {PlaceAutocompleteElement}=await google.maps.importLibrary('places');const autocomplete=new PlaceAutocompleteElement({});autocomplete.includedRegionCodes=['in'];autocomplete.locationBias={radius:35000,center:map?.getCenter?.()?.toJSON?.()||{lat:20.4625,lng:85.883}};autocomplete.placeholder='Search Cuttack road, building or locality';host.replaceChildren(autocomplete);autocomplete.addEventListener('gmp-select',async event=>{try{const place=event.placePrediction.toPlace();await place.fetchFields({fields:['formattedAddress','location']});if(!place.location||!place.formattedAddress)throw Error('Choose a result with a map location.');const point=place.location.toJSON();await selectPlace({address:place.formattedAddress,lat:point.lat,lng:point.lng})}catch(error){toast(error.message||'Could not read that address. Choose another suggestion.')}})}catch(error){console.warn('Google Places autocomplete unavailable',error);host.innerHTML='<span class="fine">Address suggestions unavailable. Use GPS or choose a map pin.</span>'}}
async function verifyGoogleAddress(addressLine,details){await loadGoogleMaps();const {AddressValidation}=await google.maps.importLibrary('addressValidation');const result=await AddressValidation.fetchAddressValidation({address:{regionCode:'IN',languageCode:'en',addressLines:[addressLine,details].filter(Boolean)}});const verdict=result.verdict||{},point=result.geocode?.location,formattedAddress=result.address?.formattedAddress;if(!formattedAddress||!point||verdict.validationGranularity==='OTHER')throw Error('Google could not verify this address. Choose a Places suggestion or add the road/building name and try again.');return{formattedAddress,complete:verdict.addressComplete===true,granularity:verdict.validationGranularity||'UNKNOWN',inferred:verdict.hasInferredComponents===true,replaced:verdict.hasReplacedComponents===true}}
async function setAddressPin(lat,lng,reverseGeocode=true){const form=document.querySelector('#address-form');if(!form)return;form.elements.lat.value=String(lat);form.elements.lng.value=String(lng);const position={lat,lng};if(addressMap&&addressMarker){addressMarker.setPosition(position);addressMap.setCenter(position);addressMap.setZoom(17)}const status=document.querySelector('#location-status');if(!reverseGeocode){if(status)status.textContent='Saved pin selected. Add a nearby landmark or exact directions.';return}if(status)status.textContent='Pin selected. Looking up the street address…';try{await loadGoogleMaps();addressGeocoder=addressGeocoder||new google.maps.Geocoder();const {results}=await addressGeocoder.geocode({location:position,region:'IN'});if(results?.[0]){form.elements.addressLine.value=results[0].formatted_address;form.elements.addressLine.readOnly=false;if(status)status.textContent='Address filled from the pin. Add a nearby landmark or exact directions if needed.'}else throw Error('ZERO_RESULTS')}catch(error){console.warn('Address reverse geocoding failed',error);form.elements.addressLine.readOnly=false;const reason=String(error?.message||error).toUpperCase();if(status)status.textContent=reason.includes('REQUEST_DENIED')||reason.includes('API KEY')?'Pin saved, but Google address lookup is disabled. Enable Geocoding API in the same Google Cloud project as Maps JavaScript API.':'Pin saved. No street address was returned; add the nearest road or landmark.'}}
function useDeviceLocation(){const status=document.querySelector('#location-status');if(!navigator.geolocation){if(status)status.textContent='This browser does not support device location.';return}if(status)status.textContent='Requesting your location…';navigator.geolocation.getCurrentPosition(position=>setAddressPin(position.coords.latitude,position.coords.longitude),error=>{if(status)status.textContent=error.code===1?'Location permission was denied. Allow location access or choose a pin on the map.':error.code===2?'Your device could not determine its location. Try moving to an open area or choose a map pin.':'Location lookup took too long. Try again or choose a map pin.'},{enableHighAccuracy:true,timeout:12000,maximumAge:60000})}
async function initializeAddressPicker(){const wrap=document.querySelector('#address-map-wrap'),mapElement=document.querySelector('#address-map');if(!wrap||!mapElement)return;document.querySelector('#use-current-location')?.addEventListener('click',useDeviceLocation);if(!catalog.googleMapsApiKey){wrap.classList.add('map-unavailable');const status=document.querySelector('#location-status');if(status)status.textContent='Use device location to pin the address. Interactive Google Maps will appear once the Maps key is configured.';return}try{await loadGoogleMaps();if(!document.body.contains(mapElement))return;const saved=catalog.addresses[0];const start=saved?{lat:saved.lat,lng:saved.lng}:{lat:20.4625,lng:85.883};addressMap=new google.maps.Map(mapElement,{center:start,zoom:saved?15:12,mapTypeControl:false,streetViewControl:false,fullscreenControl:false,clickableIcons:false});addressGeocoder=new google.maps.Geocoder();addressMarker=new google.maps.Marker({position:start,map:addressMap,draggable:true,title:'Wash service location'});addressMap.addListener('click',event=>{if(event.latLng)setAddressPin(event.latLng.lat(),event.latLng.lng())});addressMarker.addListener('dragend',event=>{if(event.latLng)setAddressPin(event.latLng.lat(),event.latLng.lng())});await mountAddressAutocomplete(document.querySelector('#address-autocomplete'),async place=>{await setAddressPin(place.lat,place.lng,false);const form=document.querySelector('#address-form');if(form)form.elements.addressLine.value=place.address;const status=document.querySelector('#location-status');if(status)status.textContent='Address selected. Add your nearby landmark, then verify and save.'},addressMap);if(saved){setAddressPin(saved.lat,saved.lng,false)}}catch(error){wrap.classList.add('map-unavailable');const status=document.querySelector('#location-status');if(status)status.textContent='Google Maps did not load. Use device location or check the Maps API key and website restrictions.'}}
