 let bookingMap=null,bookingMarker=null,bookingGeocoder=null,bookingMapPromise=null;const fillBookingPin=async(lat,lng)=>{form.elements.lat.value=String(lat);form.elements.lng.value=String(lng);const pos={lat,lng},status=document.querySelector('#booking-location-status');if(bookingMarker){bookingMarker.setPosition(pos);bookingMap?.setCenter(pos);bookingMap?.setZoom(17)}updateServices();if(status)status.textContent='Pin selected. Finding the street address…';try{await loadGoogleMaps();bookingGeocoder=bookingGeocoder||new google.maps.Geocoder();const result=await bookingGeocoder.geocode({location:pos,region:'IN'});if(result.results?.[0]){form.elements.addressLine.value=result.results[0].formatted_address;form.elements.addressLine.readOnly=false;if(status)status.textContent='Address filled from your pin. Add a nearby landmark or exact directions if needed.'}else throw Error('ZERO_RESULTS')}catch(error){console.warn('Booking reverse geocoding failed',error);form.elements.addressLine.readOnly=false;const reason=String(error?.message||error).toUpperCase();if(status)status.textContent=reason.includes('REQUEST_DENIED')||reason.includes('API KEY')?'Pin saved, but Google address lookup is disabled. Enable Geocoding API in the same Google Cloud project as Maps JavaScript API.':'Pin saved. No street address was returned; add the nearest road or landmark.'}};const initBookingMap=()=>{if(bookingMap||bookingMapPromise||!catalog.googleMapsApiKey)return;bookingMapPromise=loadGoogleMaps().then(async()=>{const mapElement=document.querySelector('#booking-address-map');if(!mapElement||!modal.isConnected)return;const start=catalog.addresses[0]?{lat:catalog.addresses[0].lat,lng:catalog.addresses[0].lng}:{lat:20.4625,lng:85.883};bookingMap=new google.maps.Map(mapElement,{center:start,zoom:catalog.addresses.length?15:13,mapTypeControl:false,streetViewControl:false,fullscreenControl:false,clickableIcons:false});bookingGeocoder=new google.maps.Geocoder();bookingMarker=new google.maps.Marker({map:bookingMap,draggable:true,title:'Your wash location'});bookingMap.addListener('click',event=>{if(event.latLng)fillBookingPin(event.latLng.lat(),event.latLng.lng())});bookingMarker.addListener('dragend',event=>{const pos=bookingMarker.getPosition();if(pos)fillBookingPin(pos.lat(),pos.lng())});await mountAddressAutocomplete(document.querySelector('#booking-address-autocomplete'),async place=>{form.elements.lat.value=String(place.lat);form.elements.lng.value=String(place.lng);bookingMarker.setPosition(place);bookingMap.setCenter(place);bookingMap.setZoom(17);form.elements.addressLine.value=place.address;form.elements.addressLine.readOnly=false;updateServices();const status=document.querySelector('#booking-location-status');if(status)status.textContent='Address selected. Add nearby directions, then continue.'},bookingMap)}).catch(()=>{document.querySelector('#booking-map-wrap')?.classList.add('map-unavailable');const status=document.querySelector('#booking-location-status');if(status)status.textContent='Map could not load. Use GPS; if address lookup fails, enter a nearby street or landmark.'})};
 vehicle.onchange=toggleVehicle;form.elements.newVehicleType.onchange=updateServices;category.onchange=toggleVehicle;address.onchange=toggleAddress;service.onchange=updateBookingTotal;
