function base64UrlBytes(value){const padding='='.repeat((4-value.length%4)%4),base64=(value+padding).replace(/-/g,'+').replace(/_/g,'/');return Uint8Array.from(atob(base64),c=>c.charCodeAt(0))}
async function initializeMarketingPreferences(){const form=document.querySelector('#marketing-preferences');if(!form)return;const push=document.querySelector('#push-settings');try{const prefs=await api('/api/v1/marketing/preferences');form.elements.optedIn.checked=prefs.optedIn;push.innerHTML=prefs.pushReady?(prefs.pushEnabled?'<span class="fine">Push notifications are enabled on this device.</span><button class="secondary" id="push-disable" type="button">Turn off push here</button>':'<button class="secondary" id="push-enable" type="button" '+(prefs.optedIn?'':'disabled')+'>Enable push notifications</button><span class="fine">Browser permission is requested only after you choose Enable.</span>'):'<span class="fine">Push notifications are not configured for this site yet.</span>';form.onsubmit=async event=>{event.preventDefault();try{const result=await api('/api/v1/marketing/preferences',{method:'PUT',body:JSON.stringify({optedIn:form.elements.optedIn.checked})});toast(result.optedIn?'Offer preferences saved':'Marketing offers turned off');await initializeMarketingPreferences()}catch(error){toast(error.message)}};document.querySelector('#push-enable')?.addEventListener('click',async()=>{try{if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw Error('This browser does not support push notifications.');if(!prefs.optedIn)throw Error('Turn on offer consent and save first.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Allow notifications in your browser to continue.');const registration=await navigator.serviceWorker.ready,subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:base64UrlBytes(prefs.vapidPublicKey)});const serialized=subscription.toJSON();await api('/api/v1/push/subscribe',{method:'POST',body:JSON.stringify({endpoint:serialized.endpoint,keys:serialized.keys})});toast('Push notifications enabled on this device');await initializeMarketingPreferences()}catch(error){toast(error.message)}});document.querySelector('#push-disable')?.addEventListener('click',async()=>{try{const registration=await navigator.serviceWorker.ready,subscription=await registration.pushManager.getSubscription();if(subscription){await api('/api/v1/push/subscribe',{method:'DELETE',body:JSON.stringify({endpoint:subscription.endpoint})});await subscription.unsubscribe()}toast('Push notifications disabled on this device');await initializeMarketingPreferences()}catch(error){toast(error.message)}})}catch(error){push.innerHTML='<span class="fine">Could not load notification settings. '+esc(error.message)+'</span>'}}
function bindCommon(){bindPhotoReview();initializeAddressPicker();initializeMarketingPreferences();document.querySelectorAll('[data-notification-retry]').forEach(b=>b.onclick=async()=>{try{await api('/api/v1/admin/notifications/'+encodeURIComponent(b.dataset.notificationRetry)+'/retry',{method:'POST',body:JSON.stringify({})});await render();toast('Notification queued for retry')}catch(e){toast(e.message)}});document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>{openBooking()});document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{try{await api('/api/v1/bookings/'+encodeURIComponent(b.dataset.cancel)+'/cancel',{method:'POST'});await render();toast('Booking cancelled')}catch(e){toast(e.message)}});document.querySelectorAll('[data-pay]').forEach(b=>b.onclick=()=>pay(b.dataset.pay));document.querySelector('#vehicle-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/v1/vehicles',{method:'POST',body:JSON.stringify(d)});await render();toast('Vehicle added')}catch(x){toast(x.message)}});document.querySelector('#address-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.lat=Number(d.lat);d.lng=Number(d.lng);if(!Number.isFinite(d.lat)||!Number.isFinite(d.lng)||d.lat < -90||d.lat > 90||d.lng < -180||d.lng > 180)return toast('Select your location on the map or use your device location first.');const validationStatus=document.querySelector('#address-validation-status');try{if(validationStatus)validationStatus.textContent='Checking and standardizing this address with Google…';const validation=await verifyGoogleAddress(d.addressLine,d.details);d.addressLine=validation.formattedAddress;d.fullAddress=d.addressLine+(d.details?' — '+d.details:'');if(validationStatus)validationStatus.textContent=validation.complete?'Address verified. Checking your service zone…':'Address checked. The pin and landmark will guide the wash partner to the exact point.';const saved=await api('/api/v1/addresses',{method:'POST',body:JSON.stringify(d)});catalog.addresses.push(saved);root.innerHTML=addressView();bindCommon();toast('Address saved')}catch(x){const validationStatus=document.querySelector('#address-validation-status');if(validationStatus)validationStatus.textContent=x.message;toast(x.message)}});document.querySelector('#online-toggle')?.addEventListener('click',async()=>{try{const online=!workerProfile.isOnline;await api('/api/v1/worker/online',{method:'PATCH',body:JSON.stringify({online})});if(online&&navigator.geolocation)await new Promise(resolve=>navigator.geolocation.getCurrentPosition(async p=>{try{await api('/api/v1/worker/location',{method:'PATCH',body:JSON.stringify({lat:p.coords.latitude,lng:p.coords.longitude})})}catch{}resolve()},()=>resolve(),{enableHighAccuracy:true,timeout:8000,maximumAge:60000}));workerProfile=await api('/api/v1/worker/profile');await render()}catch(e){toast(e.message)}});document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=async()=>{try{await api('/api/v1/worker/jobs/'+encodeURIComponent(b.dataset.accept)+'/accept',{method:'POST'});await render();toast('Job accepted')}catch(e){toast(e.message)}});document.querySelectorAll('[data-status]').forEach(b=>b.onclick=async()=>{try{await api('/api/v1/worker/bookings/'+encodeURIComponent(b.dataset.status)+'/status',{method:'PATCH',body:JSON.stringify({status:b.dataset.next})});await render();toast('Booking status updated')}catch(e){toast(e.message)}});document.querySelectorAll('[data-photo-booking]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await uploadPhotos(f.dataset.photoBooking,f.elements.type.value,Array.from(f.elements.files.files));await render();toast('Photos uploaded for admin review')}catch(x){toast(x.message)}});document.querySelector('#campaign-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const data={name:f.get('name'),zoneId:f.get('zoneId'),startDate:new Date(f.get('startDate')).toISOString(),endDate:new Date(f.get('endDate')).toISOString(),surgePct:Number(f.get('surgePct')),tempWorkersNeeded:Number(f.get('tempWorkersNeeded'))};try{await api('/api/v1/admin/campaigns',{method:'POST',body:JSON.stringify(data)});await render();toast('Campaign created')}catch(x){toast(x.message)}});document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=async()=>{const stars=Number(prompt('Rate the completed service from 1 to 5 stars'));if(!stars)return;try{await api('/api/v1/bookings/'+encodeURIComponent(b.dataset.rate)+'/rating',{method:'POST',body:JSON.stringify({stars})});await render();toast('Rating saved')}catch(e){toast(e.message)}});document.querySelector('#worker-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/v1/admin/workers',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});await render();toast('Worker account created. They can set a password or sign in with Google using this email.')}catch(x){toast(x.message)}});document.querySelector('#worker-zone-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/admin/workers/'+encodeURIComponent(f.get('workerId'))+'/zones/'+encodeURIComponent(f.get('zoneId')),{method:'PUT'});toast('Worker assigned to zone')}catch(x){toast(x.message)}});document.querySelector('#zone-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/admin/zones',{method:'POST',body:JSON.stringify({name:f.get('name'),baseCommissionPct:Number(f.get('baseCommissionPct')),polygon:JSON.parse(f.get('polygon'))})});await render();toast('Zone created')}catch(x){toast(x.message)}});document.querySelectorAll('[data-zone-toggle]').forEach(b=>b.onclick=async()=>{try{await api('/api/v1/admin/zones/'+encodeURIComponent(b.dataset.zoneToggle),{method:'PATCH',body:JSON.stringify({isActive:b.dataset.active!=='true'})});await render()}catch(e){toast(e.message)}});document.querySelector('#service-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.durationMin=Number(d.durationMin);try{await api('/api/v1/admin/services',{method:'POST',body:JSON.stringify(d)});await render();toast('Service created')}catch(x){toast(x.message)}});document.querySelector('#price-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),type=e.currentTarget.elements.serviceId.selectedOptions[0].dataset.type;try{await api('/api/v1/admin/zones/'+encodeURIComponent(f.get('zoneId'))+'/prices/'+encodeURIComponent(f.get('serviceId')),{method:'PUT',body:JSON.stringify({price:Math.round(Number(f.get('price'))*100),vehicleType:type})});await render();toast('Zone price saved')}catch(x){toast(x.message)}});document.querySelector('#payout-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/v1/admin/payouts',{method:'POST',body:JSON.stringify({workerId:f.get('workerId'),amount:Math.round(Number(f.get('amount'))*100)})});await render();toast('Payout created')}catch(x){toast(x.message)}});document.querySelectorAll('[data-kyc]').forEach(b=>b.onclick=async()=>{try{await api('/api/v1/admin/workers/'+encodeURIComponent(b.dataset.kyc)+'/kyc',{method:'PATCH',body:JSON.stringify({status:'APPROVED'})});await render()}catch(e){toast(e.message)}});document.querySelectorAll('[data-block]').forEach(b=>b.onclick=async()=>{try{await api('/api/v1/admin/workers/'+encodeURIComponent(b.dataset.block)+'/block',{method:'PATCH'});await render()}catch(e){toast(e.message)}});document.querySelectorAll('[data-assign]').forEach(b=>b.onclick=async()=>{try{const solar=b.dataset.category==='SOLAR',eligible=await api('/api/v1/admin/bookings/'+encodeURIComponent(b.dataset.assign)+'/eligible-workers');if(!eligible.length)return toast(solar?'No approved, online Solar-qualified worker is assigned to this zone or currently inside it.':'No approved online worker is assigned to this zone or currently inside it.');const choice=prompt('Choose worker number:\n'+eligible.map((w,i)=>(i+1)+'. '+(w.user.name||w.user.email)).join('\n'));const worker=eligible[Number(choice)-1];if(!worker)return;await api('/api/v1/admin/bookings/'+encodeURIComponent(b.dataset.assign)+'/assign',{method:'POST',body:JSON.stringify({workerId:worker.id})});await render();toast('Booking assigned')}catch(e){toast(e.message)}});document.querySelectorAll('[data-paid]').forEach(b=>b.onclick=async()=>{const utr=prompt('Enter the bank/UPI transfer reference (UTR):');if(!utr)return;try{await api('/api/v1/admin/payouts/'+encodeURIComponent(b.dataset.paid)+'/mark-paid',{method:'POST',body:JSON.stringify({utr})});await render()}catch(e){toast(e.message)}});document.querySelectorAll('[data-delete-vehicle]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this vehicle?'))return;try{await api('/api/v1/vehicles/'+encodeURIComponent(b.dataset.deleteVehicle),{method:'DELETE'});await render()}catch(e){toast(e.message)}});document.querySelectorAll('[data-delete-address]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this address?'))return;try{await api('/api/v1/addresses/'+encodeURIComponent(b.dataset.deleteAddress),{method:'DELETE'});catalog.addresses=catalog.addresses.filter(a=>a.id!==b.dataset.deleteAddress);root.innerHTML=addressView();bindCommon()}catch(e){toast(e.message)}});}
document.addEventListener('click',async event=>{const refundButton=event.target.closest('[data-refund]');if(refundButton){const max=Number(refundButton.dataset.remaining||0)/100,amount=Number(prompt('Refund amount in ₹ (up to ₹'+max.toFixed(2)+'):',max.toFixed(2)));if(!Number.isFinite(amount)||amount<=0)return;const reason=prompt('Refund reason (required):','Customer cancellation');if(!reason||reason.trim().length<4)return toast('Enter a refund reason.');try{const result=await api('/api/v1/admin/bookings/'+encodeURIComponent(refundButton.dataset.refund)+'/refunds',{method:'POST',body:JSON.stringify({amount:Math.round(amount*100),reason:reason.trim(),idempotencyKey:crypto.randomUUID()})});await render();toast('Refund '+result.status.toLowerCase()+'. Use Reconcile Cashfree to confirm its latest status.')}catch(error){toast(error.message)}return}const reconcileButton=event.target.closest('[data-reconcile]');if(reconcileButton){try{const result=await api('/api/v1/admin/bookings/'+encodeURIComponent(reconcileButton.dataset.reconcile)+'/payment-reconciliation');await render();toast('Cashfree refreshed. '+result.refunds.length+' refund record(s) reconciled.')}catch(error){toast(error.message)}}});
async function pay(id){try{const order=await api('/api/v1/bookings/'+encodeURIComponent(id)+'/payment-order',{method:'POST'});if(!window.Cashfree){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://sdk.cashfree.com/js/v3/cashfree.js';s.onload=resolve;s.onerror=reject;document.head.append(s)})}const cashfree=window.Cashfree({mode:order.mode});await cashfree.checkout({paymentSessionId:order.paymentSessionId,redirectTarget:'_self'})}catch(e){toast(e.message)}}
async function uploadPhotos(bookingId,type,files){if(!files.length)throw Error('Choose at least one photo.');const location=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lng:p.coords.longitude}),()=>reject(Error('Location permission is needed to attach job GPS.')),{enableHighAccuracy:true,timeout:10000}));for(const file of files){if(file.size>10*1024*1024)throw Error('Each image must be 10 MB or smaller.');const signed=await api('/api/v1/worker/bookings/'+encodeURIComponent(bookingId)+'/photos/presign',{method:'POST',body:JSON.stringify({type,contentType:file.type})});const uploaded=await fetch(signed.uploadUrl,{method:'PUT',headers:{'Content-Type':file.type},body:file});if(!uploaded.ok)throw Error('Could not upload a photo to private storage. Check storage bucket CORS.');await api('/api/v1/worker/bookings/'+encodeURIComponent(bookingId)+'/photos',{method:'POST',body:JSON.stringify({type,objectKey:signed.objectKey,capturedAt:new Date(file.lastModified||Date.now()).toISOString(),lat:location.lat,lng:location.lng})})}}
function bindPhotoReview(){document.querySelectorAll('[data-photo-view]').forEach(b=>b.onclick=async()=>{try{const d=await api('/api/v1/photos/'+encodeURIComponent(b.dataset.photoView)+'/view');const modal=document.createElement('div');modal.className='backdrop';modal.innerHTML='<div class="modal"><button class="close">Close</button><img class="preview-image" alt="Booking evidence" src="'+esc(d.url)+'"></div>';document.body.append(modal);modal.querySelector('.close').onclick=()=>modal.remove()}catch(e){toast(e.message)}});document.querySelectorAll('[data-photo-review]').forEach(b=>b.onclick=async()=>{try{await api('/api/v1/admin/photos/'+encodeURIComponent(b.dataset.photoReview),{method:'PATCH',body:JSON.stringify({status:b.dataset.decision})});await render();toast('Photo review saved')}catch(e){toast(e.message)}})}
async function boot(){const started=performance.now();try{me=await api('/api/v1/me');customerCacheLoaded=false;view=me.role==='CUSTOMER'?'Overview':me.role==='WORKER'?'Job requests':'Bookings';if(me.role==='ADMIN'){try{const mfa=await api('/api/v1/admin/security/mfa');if(mfa.required&&!mfa.enabled)view='Security'}catch{}}await render();console.info('QuickWashHub dashboard shell ready',Math.round(performance.now()-started)+'ms');if(me.role==='CUSTOMER')setTimeout(showFirstInstallDialog,1200)}catch{me=null;authPage()}}
boot();
